<?php use Simit\Core\Csrf; ?>
<div class="approval-list"><?php foreach($rows as $task):?><article class="panel approval-card"><div class="approval-main"><p class="eyebrow"><?=e($task['number'])?> · <?=e($task['assignee']??'User')?></p><h2><?=e($task['title'])?></h2><p class="result-text"><?=nl2br(e($task['result']??'-'))?></p><a class="link-btn" href="/tugas/hasil/<?=$task['id']?>"><?=__('Lihat hasil dan lampiran','View result and attachments')?></a></div><div class="approval-actions"><form method="post" action="/persetujuan/approve/<?=$task['id']?>"><?=Csrf::field()?><label><?=__('Catatan admin (opsional)','Admin note (optional)')?><textarea name="note" rows="2"></textarea></label><button class="btn primary"><?=__('Setujui','Approve')?></button></form><form method="post" action="/persetujuan/reject/<?=$task['id']?>"><?=Csrf::field()?><label><?=__('Alasan revisi','Revision reason')?><textarea name="note" rows="2" required></textarea></label><button class="btn ghost"><?=__('Kembalikan ke user','Return to user')?></button></form></div></article><?php endforeach;?><?php if(!$rows):?><div class="panel empty"><?=__('Tidak ada tugas yang menunggu ACC.','No tasks are waiting for approval.')?></div><?php endif;?></div>
